namespace Payments;

public sealed class SettlementBatchProcessor
{
    public SettlementResult Process(string merchantId, IEnumerable<PaymentItem> items, string settlementCurrency,
        decimal percentageFee, decimal fixedFee, decimal submissionLimit, ISettlementGateway gateway)
    {
        var lines = new List<SettlementLine>();
        var accepted = new List<AcceptedPayment>();
        var seen = new HashSet<string>(StringComparer.Ordinal);

        foreach (var item in items)
        {
            var assessment = Assess(item, settlementCurrency, percentageFee, fixedFee, submissionLimit, seen, accepted);
            if (assessment.RejectionReason is not null)
            {
                lines.Add(new SettlementLine(item.Reference, 0m, assessment.RejectionReason));
                continue;
            }

            accepted.Add(new AcceptedPayment(item.Reference, assessment.Net));
        }

        return CompleteSettlement(merchantId, settlementCurrency, gateway, lines, accepted);
    }

    private static ItemAssessment Assess(PaymentItem item, string settlementCurrency, decimal percentageFee,
        decimal fixedFee, decimal submissionLimit, HashSet<string> seen, List<AcceptedPayment> accepted)
    {
        var rejectionReason = GetEligibilityRejection(item, settlementCurrency, seen);
        if (rejectionReason is not null)
            return new ItemAssessment(0m, rejectionReason);

        var fee = decimal.Round(item.GrossAmount * percentageFee + fixedFee, 2);
        var net = decimal.Round(item.GrossAmount - fee, 2);

        if (net <= 0m)
            return new ItemAssessment(0m, "fee-exceeds-amount");
        if (accepted.Sum(entry => entry.Net) + net > submissionLimit)
            return new ItemAssessment(0m, "batch-limit");

        return new ItemAssessment(net, null);
    }

    private static string? GetEligibilityRejection(PaymentItem item, string settlementCurrency, HashSet<string> seen)
    {
        if (string.IsNullOrWhiteSpace(item.Reference))
            return "invalid-reference";
        if (!seen.Add(item.Reference))
            return "duplicate";
        if (!string.Equals(item.Currency, settlementCurrency, StringComparison.OrdinalIgnoreCase))
            return "currency-mismatch";
        if (item.GrossAmount <= 0m)
            return "invalid-amount";
        if (item.Refunded)
            return "refunded";
        if (item.Held)
            return "held";

        return null;
    }

    private static SettlementResult CompleteSettlement(string merchantId, string settlementCurrency,
        ISettlementGateway gateway, List<SettlementLine> lines, List<AcceptedPayment> accepted)
    {
        if (accepted.Count == 0)
            return new SettlementResult(lines, 0m, "empty");

        if (string.IsNullOrWhiteSpace(merchantId))
        {
            return new SettlementResult(
                [.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, "invalid-merchant"))],
                0m,
                "rejected");
        }

        var total = accepted.Sum(entry => entry.Net);
        var gatewayResult = gateway.Submit(
            merchantId,
            settlementCurrency,
            total,
            accepted.Select(entry => entry.Reference).ToArray());

        if (!gatewayResult.Accepted)
        {
            return new SettlementResult(
                [.. lines, .. accepted.Select(entry => new SettlementLine(entry.Reference, 0m, $"gateway-{gatewayResult.Code}"))],
                0m,
                "rejected");
        }

        lines.AddRange(accepted.Select(entry => new SettlementLine(entry.Reference, entry.Net, "submitted")));
        return new SettlementResult(
            lines,
            total,
            lines.Any(line => line.Status != "submitted") ? "partial" : "submitted");
    }

    private readonly record struct AcceptedPayment(string Reference, decimal Net);

    private readonly record struct ItemAssessment(decimal Net, string? RejectionReason);
}
